	'messages:apierror-compare-no-title' => 'en:Cannot pre-save transform without a title. Try specifying <var>fromtitle</var> or <var>totitle</var>.',
	'messages:apierror-compare-nosuchfromsection' => 'en:There is no section $1 in the \'from\' content.',
